package dev.giljabi;
import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class GeminiModelsTest {
 @Test public void listContainsOnlyReturnedGenerationModels()throws Exception{String data="{\"models\":[{\"name\":\"models/gemini-3.8-flash\",\"supportedGenerationMethods\":[\"generateContent\"]},{\"name\":\"models/gemini-3.8-flash-tts\",\"supportedGenerationMethods\":[\"generateContent\"]},{\"name\":\"models/gemini-2.5-pro\",\"supportedGenerationMethods\":[\"countTokens\"]},{\"name\":\"models/gemini-3.1-flash-lite\",\"supportedGenerationMethods\":[\"generateContent\"]}]}";assertEquals(Arrays.asList("gemini-3.1-flash-lite","gemini-3.8-flash"),GeminiModels.parse(data));}
 @Test public void invalidKeyReasonIsHelpfulWithoutEchoingRawBody(){String raw="{\"error\":{\"message\":\"secret-do-not-echo\",\"details\":[{\"reason\":\"API_KEY_INVALID\"}]}}";String e=GeminiClient.apiError(400,raw.getBytes(StandardCharsets.UTF_8));assertTrue(e.contains("키"));assertFalse(e.contains("secret"));}
 @Test public void serverOverloadIsNotCalledBadInternet(){assertTrue(GeminiClient.httpError(503).contains("서버 혼잡"));assertTrue(GeminiClient.httpError(429).contains("한도"));assertTrue(GeminiClient.httpError(404).contains("모델"));}
 @Test public void catalogUsesHeaderAndCannotFollowRedirect()throws Exception{GeminiClientTest.Connection c=new GeminiClientTest.Connection();c.code=307;try(GeminiModels.Request request=new GeminiModels.Request(GeminiClientTest.KEY,url->{assertEquals("generativelanguage.googleapis.com",url.getHost());assertFalse(url.toString().contains(GeminiClientTest.KEY));return c;},()->false)){assertThrows(IOException.class,request::execute);}assertEquals(GeminiClientTest.KEY,c.getRequestProperty("x-goog-api-key"));assertFalse(c.getInstanceFollowRedirects());assertTrue(c.disconnected);}
}
